// Custom pointer: hide the system cursor and draw a crosshair overlay that follows the mouse.
export function Crosshair() {
  useEffect(() => {
    document.documentElement.style.cursor = 'none';
    const move = (e: PointerEvent) => setPos({ x: e.clientX, y: e.clientY });
    window.addEventListener('pointermove', move);
    return () => window.removeEventListener('pointermove', move);
  }, []);
}

const LETTER_KEYS: Record<string, string> = { e: 'email', l: 'linkedin', g: 'github', i: 'instagram', y: 'youtube' };
function onKeyDown(event: KeyboardEvent) {
  const id = LETTER_KEYS[event.key];
  if (!id) return;
  open(id);
}

const VIEW_KEYS = { m: 'me', s: 'stats', b: 'builds', w: 'work', o: 'more', t: 'talk' };
function onKey(event: KeyboardEvent) {
  const view = VIEW_KEYS[event.key];
  if (view) router.push('/' + view);
}

import Hero from '@/components/Hero';
export default function Demo() {
  return <section><h2>landing typing</h2><Hero /></section>;
}
